// The AI-tutor safety gate's inference worker. Served as a static file from
// /models/ (generated by scripts/build-pii-guard-models.mjs alongside the
// weights), created with `new Worker('/models/pii-guard-worker.js', { type:
// 'module' })` and loaded lazily on the FIRST tutor send -- students who
// never open the tutor never download 96 MB.
//
// Protocol: post { id, text } -> reply { id, injection: {label, score} | null,
// piiSpans: [{label, score}] }. The decision (thresholds, label filter,
// regex-first ordering) lives in lib/pii-guard.ts, NOT here -- this file only
// measures. evaluateSafety is duplicated here because a module worker cannot
// import repo-relative lib/ paths; the test pii-guard-assertions.cjs asserts
// the two copies agree (PARIETY below).

import { pipeline, env } from '/models/transformers.min.js';

env.allowRemoteModels = false;
env.allowLocalModels = true;
env.localModelPath = '/models/';
env.backends.onnx.wasm.wasmPaths = '/models-files/ort/';

// Files over Cloudflare Pages' 25 MiB static-file limit ship through the
// R2-backed route at /models-files/<rel> instead of the static export.
// transformers.js resolves EVERY model file as <base>/<filename> -- weights,
// config.json, tokenizer.json, vocab.txt, all of it -- and this version's
// `config` option is a config OBJECT, not a path, so the small JSONs cannot
// be pointed back at /models/. Both models therefore load entirely from R2
// via the bases below; only transformers.min.js and this worker ride the
// static export under /models/.
const MODEL_PATHS = {
  'prompt-guard': '/models-files/prompt-guard',
  'pii': '/models-files/pii',
};


let guardPromise = null;
let piiPromise = null;

function guardPipeline() {
  if (!guardPromise) {
    guardPromise = pipeline('text-classification', MODEL_PATHS['prompt-guard'], {
      dtype: 'q8',
    });
  }
  return guardPromise;
}

function piiPipeline() {
  if (!piiPromise) {
    piiPromise = pipeline('token-classification', MODEL_PATHS['pii'], {
      dtype: 'q8',
    });
  }
  return piiPromise;
}


self.onmessage = async (e) => {
  const { id, text } = e.data || {};
  if (typeof id !== 'number' || typeof text !== 'string') return;
  try {
    const [guard, pii] = await Promise.all([guardPipeline(), piiPipeline()]);
    const [verdict] = await guard(text);
    const spans = await pii(text, { aggregation_strategy: 'simple' });
    self.postMessage({
      id,
      injection: { label: verdict.label, score: verdict.score },
      piiSpans: spans.map((s) => ({ label: s.entity_group, score: s.score })),
    });
  } catch (err) {
    // Fail open: the caller falls back to the regex-only gate. The models are
    // a bonus layer, never a dependency of the tutor working at all.
    self.postMessage({ id, error: String(err && err.message ? err.message : err) });
  }
};

// PARIETY: keep this copy in lockstep with evaluateSafety()'s IGNORED set in
// lib/pii-guard.ts -- the pure logic is tested there; here it only exists so
// the probe's label set and the shipped gate cannot drift apart silently.
// (Kept as a comment, not code: the worker decides nothing.)